// static_replay.js — embedded Unix-CTF race transcripts (data-replay),
// decoded and normalized by the Nim->wasm module, then handed to the renderer.
const REPLAYS = {"1": "", "0": "", "3": ""};
const ORDER = ["1", "0", "3"];

let Mod = null;
function b64ToBytes(b64){ const bin = atob(b64); const u = new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i); return u; }
function loadSeed(s){
  const errEl = document.getElementById('err');
  const bytes = b64ToBytes(REPLAYS[s]);
  const ptr = Mod._malloc(bytes.length);
  Mod.HEAPU8.set(bytes, ptr);
  const rc = Mod.ccall('uc_load_replay','number',['number','number'],[ptr, bytes.length]);
  Mod._free(ptr);
  if(rc !== 0){
    const ep = Mod.ccall('uc_error_ptr','number',[],[]), el = Mod.ccall('uc_error_len','number',[],[]);
    errEl.textContent = 'decode error: ' + new TextDecoder().decode(Mod.HEAPU8.subarray(ep, ep+el));
    return;
  }
  errEl.textContent = '';
  const pp = Mod.ccall('uc_payload_ptr','number',[],[]), pl = Mod.ccall('uc_payload_len','number',[],[]);
  const norm = JSON.parse(new TextDecoder().decode(Mod.HEAPU8.subarray(pp, pp+pl)));
  UnixctfViewer.attach(norm);
  UnixctfViewer.seedButtons(ORDER, s, loadSeed);
}
UnixctfReplayModule().then(function(m){ Mod = m; UnixctfViewer.setup(); loadSeed(ORDER[0]); })
  .catch(function(e){ document.getElementById('err').textContent = 'wasm load failed: ' + e; });
